package com.nyayaconnect.appointment;
import com.nyayaconnect.auth.SpringAccess;import com.nyayaconnect.common.Api;import com.nyayaconnect.common.Json;import com.nyayaconnect.security.AuthenticationFilter;import com.nyayaconnect.security.SessionUser;import jakarta.servlet.http.*;import java.io.IOException;import java.util.Map;import java.util.UUID;
public final class AppointmentActionServlet extends HttpServlet { private AppointmentService service; public void init(){service=SpringAccess.bean(getServletContext(),AppointmentService.class);}
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{try{SessionUser u=(SessionUser)req.getSession(false).getAttribute(AuthenticationFilter.SESSION_KEY);String[] p=req.getPathInfo().split("/");if(p.length<3)throw new IllegalArgumentException("Appointment action is required.");UUID id=UUID.fromString(p[1]);String action=p[2];String correlation=String.valueOf(req.getAttribute("X-Correlation-Id"));switch(action){case "confirm"->service.confirm(u,id,req.getRemoteAddr(),correlation);case "reject"->service.reject(u,id,req.getRemoteAddr(),correlation);case "complete"->{Map<?,?> b=Json.MAPPER.readValue(req.getInputStream(),Map.class);service.complete(u,id,String.valueOf(b.get("notes") == null ? "" : b.get("notes")),req.getRemoteAddr(),correlation);}default->throw new IllegalArgumentException("Unknown appointment action.");}Api.json(res,200,Map.of("status","UPDATED","appointmentId",id));}catch(SecurityException e){Api.error(res,403,"FORBIDDEN",e.getMessage());}catch(IllegalArgumentException e){Api.error(res,400,"INVALID_REQUEST",e.getMessage());}catch(Exception e){Api.error(res,409,"APPOINTMENT_UPDATE_FAILED","Appointment update could not be completed.");}}
}
